class DSU:
    __slots__ = ("parent", "rank", "par", "components")

    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.par = [0] * n
        self.components = n

    def find(self, x):
        if self.parent[x] != x:
            r, p = self.find(self.parent[x])
            self.par[x] ^= p
            self.parent[x] = r
        return self.parent[x], self.par[x]

    def unite(self, x, y, w):
        # require value[x] xor value[y] == w
        rx, px = self.find(x)
        ry, py = self.find(y)

        if rx == ry:
            return (px ^ py) == w

        d = w ^ px ^ py

        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
            self.par[rx] = d
        else:
            self.parent[ry] = rx
            self.par[ry] = d
            if self.rank[rx] == self.rank[ry]:
                self.rank[rx] += 1

        self.components -= 1
        return True


